    if (!id) return `<div style="color:${t2.dim};font-size:10.5px;font-weight:700;letter-spacing:0.3px;line-height:1.3;">${esc(s.emptyLabel ?? "\u2014")}</div>`;
    const color = t2.severityColor[id] ?? t2.dim;
    const text3 = t2.severityLabel[id] ?? t2.severityFallback;
    const mark = s.safety ? "\u26A0 " : "";
