// src/core/services/IntelService.ts
var CURRENT_YEAR = 2026;
function getEraFindings(year) {
  const findings = [];
  const age = Math.max(0, CURRENT_YEAR - year);
  if (year < 1940) {
    findings.push("Knob-and-tube wiring probable in walls and attic \u2014 test for active circuits before any demo or attic work");
    findings.push("Original galvanized iron supply \u2014 measure flow rate at furthest fixture; rust-colored water = active corrosion");
    findings.push("No vapor barrier or moisture control at build \u2014 ground moisture intrusion expected at rim joist and crawl");
  }
  if (year >= 1940 && year < 1960) {
    findings.push('Asphalt floor tile (9"\xD79") \u2014 pre-1960 vinyl tile is presumed ACM; do not sand or abrade without testing');
    findings.push("Early BX armored cable \u2014 cloth braid insulation brittle after 80+ years; avoid bending; probe attic for K&T remnants");
    findings.push("Fused service panel era \u2014 check for pennied fuse sockets and overfused branch circuits");
  }
  if (year >= 1960 && year < 1973) {
    findings.push("Federal Pacific Stab-Lok panel era \u2014 breakers documented to fail on overload; verify brand at main panel cover before energizing any load");
    findings.push("Zinsco / Sylvania panel era \u2014 bus bar arc fault risk documented; remove cover and check for char marks or heat discoloration");
    findings.push("Asbestos pipe insulation common on furnace flue and attic duct elbows \u2014 do not disturb without testing");
  }
  if (year >= 1965 && year < 1975) {
    findings.push("Aluminum branch-circuit wiring era \u2014 check outlets and switches for CO/ALR marking or copper pigtails; look for warm outlet faceplates");
    findings.push("Original R-11 attic insulation \u2014 far below modern code; verify thermal bypass at rim joists and attic hatch");
  }
  if (year >= 1978 && year < 1996) {
    findings.push("Polybutylene supply line recall era (class-action settled) \u2014 inspect water heater connections, manifold, and under-sink supply; gray plastic pipe = significant defect requiring disclosure");
  } else if (year >= 1996 && year <= 2e3) {
    findings.push("Late polybutylene use \u2014 some installers used PB inventory into the late 1990s; verify at water heater and manifold connections");
  }
  if (year >= 1978 && year < 1988) {
    findings.push("EIFS/Dryvit synthetic stucco introduction era \u2014 probe wall base at grade and window heads for moisture intrusion; check kickout flashing at roof-to-wall transitions");
  }
  if (year >= 1988 && year < 1997) {
    findings.push("Louisiana Pacific hardboard siding era \u2014 check bottom courses and window sill edges for swelling, delamination, and fungal staining; common class-action trigger");
    findings.push("OSB roof sheathing introduced \u2014 inspect rake and eave edges for moisture swelling and delamination before any re-roofing");
  }
  if (year >= 2004 && year <= 2009) {
    findings.push("Chinese drywall import peak (2004\u20132009) \u2014 check for sulfur odor at electrical boxes, corroded AC evaporator coils, and pitted copper wiring; concentrated in FL, LA, MS, AL");
  }
  if (year >= 2010 && year < 2020) {
    findings.push("R-22 refrigerant phaseout era \u2014 verify refrigerant type label on condenser; R-22 systems cannot be recharged after 2020 production ban; verify R-410A conversion status");
    findings.push("First-gen tankless water heater aging \u2014 check descaling service history and burner assembly condition");
  }
  if (age >= 35 && year >= 1960) {
    findings.push(`HVAC from ~${year} build era \u2014 heat exchanger crack probability elevated at ${age}+ years; verify CO detector placement and run furnace draft test`);
  }
  return findings;
}

