function buildWebChrome(entries) {
  const links = entries.map((e) => `<a href="#${e.id}" class="lx-nav-a"><span class="lx-nav-n">${String(e.n).padStart(2, "0")}</span>${esc2(e.label)}</a>`).join("");
  return `
  <nav class="lx-rail" aria-label="Report contents">
    <div class="lx-rail-h">CONTENTS</div>
    ${links}
    <div class="lx-rail-h" style="margin-top:18px;">VIEW</div>
    <div class="lx-views">
      <button type="button" class="lx-v" data-view="full">Full report</button>
      <button type="button" class="lx-v" data-view="summary">Summary</button>
      <button type="button" class="lx-v" data-view="safety">Safety only</button>
    </div>
  </nav>
  <script>(function(){
    var d=document,r=d.documentElement;
    function set(v){
      r.setAttribute('data-view',v);
      var b=d.querySelectorAll('.lx-v');
      for(var i=0;i<b.length;i++) b[i].setAttribute('aria-current', b[i].getAttribute('data-view')===v?'true':'false');
      try{ localStorage.setItem('lx-view',v); }catch(e){}
    }
    d.addEventListener('click',function(e){
      var t=e.target;
      while(t&&t!==d){ if(t.classList&&t.classList.contains('lx-v')){ set(t.getAttribute('data-view')); return; } t=t.parentNode; }
    });
    var saved='full'; try{ saved=localStorage.getItem('lx-view')||'full'; }catch(e){}
    set(saved);
  })();</script>`;
}
function wrapHTML(body, entries = []) {
  const serverOverride = PDF_SERVER_MODE ? ".page { padding: 8px 0 0 !important; page-break-before: always !important; page-break-after: auto !important; } .page:first-child { page-break-before: avoid !important; padding-top: 0 !important; }" : "";
  const webCss = `
@media screen and (min-width:1040px){
  html[data-view] body { padding-left:250px; }
  .lx-rail{ display:block !important; position:fixed; top:0; left:0; width:250px; height:100vh;
    overflow-y:auto; padding:26px 20px; border-right:1px solid ${BORDER}; background:#fff;
    box-sizing:border-box; z-index:50; }
  .lx-rail-h{ font-family:'Roboto Mono',ui-monospace,monospace; font-size:8px; font-weight:600;
    letter-spacing:2px; color:${TEXT_DIM}; margin-bottom:10px; }
  .lx-nav-a{ display:flex; gap:10px; align-items:baseline; text-decoration:none; color:${INK};
    font-family:${SERIF}; font-size:13px; padding:7px 0; border-bottom:1px solid ${BORDER}; }
  .lx-nav-a:hover{ color:${ACCENT}; }
  .lx-nav-n{ font-family:'Roboto Mono',ui-monospace,monospace; font-size:9px; color:${ACCENT}; }
  .lx-views{ display:flex; flex-direction:column; gap:6px; }
  .lx-v{ text-align:left; font-family:${SERIF}; font-size:12.5px; padding:7px 10px; cursor:pointer;
    border:1px solid ${BORDER}; border-radius:3px; background:#fff; color:${INK}; }
  .lx-v[aria-current="true"]{ border-color:${ACCENT}; color:${ACCENT}; font-weight:600; }
  /* SUMMARY hides the reference chapters, never the findings or the analysis. */
  html[data-view="summary"] #sec-profile,
  html[data-view="summary"] #sec-systems,
  html[data-view="summary"] #sec-extras { display:none; }
  /* SAFETY keeps the analysis + findings chapter, and inside it only the hot findings. */
  html[data-view="safety"] #sec-profile,
  html[data-view="safety"] #sec-systems,
  html[data-view="safety"] #sec-extras { display:none; }
  html[data-view="safety"] .fnd:not(.fnd-hot) { display:none; }
}
/* Never on paper \u2014 both renderers print. */
@media print { .lx-rail{ display:none !important; } body{ padding-left:0 !important; } }
.lx-rail{ display:none; }`;
  return `<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8"/>
<style>${BASE_CSS}${serverOverride}${webCss}</style>
</head>
<body>${entries.length ? buildWebChrome(entries) : ""}${body}</body>
</html>`;
}
